/* ====== ЗДЕСЬ МЕНЯЕМ ТЕКСТЫ ====== */
const HER_NAME = "ты";
// например: "Аня"
const DATE_TEXT = "Пятница. 17 октября, 18:00";
// дата и время свидания
const PLACE_TEXT = "Место: пока секрет";
const AUDIO_SRC = "";
// сюда встраивается ваше голосовое (data:audio/mpeg;base64,...)
const START_DT = new Date(2026,3,4,23,42,0);
// 4 апреля 2026, 23:42 — момент, когда всё началось
const STATS = [                      // n: число, label: расшифровка
{
  n:266,
  label:"сердечек я поставил тебе, и это только в телеграме"
},
{
  n:50,
  label:"раз я писал тебе «люблю», «целую» и «обнимаю»"
},
{
  timer:true,
  label:"дней мы вместе — и я всё ещё считаю каждую секунду"
}];
const SCENES = [                     // fact: интересный факт, imgs: фото (data-URI), пусто = заглушки
{
  cap:"Кадр первый",
  title:"Наше первое свидание",
  fact:"Тогда я ещё не думал, что кажется встретил человека на всю жизнь.",
  imgs:["data:image/jpeg;base64,",
  "data:image/jpeg;base64,"]
},
{
  cap:"Кадр второй",
  title:"Наши гулянки",
  fact:"С тобой даже самый обычный день превращается в что-то, что хочется запомнить.",
  imgs:["data:image/jpeg;base64,",
  "data:image/jpeg;base64,"]
},
{
  cap:"Кадр третий",
  title:"Последний месяц",
  fact:"Кажется, самые любимые свидания из всех у нас были именно сейчас.",
  imgs:["data:image/jpeg;base64,",
  "data:image/jpeg;base64,"]
}];
/* ================================= */
for(let i=0;i<14;i++) {
  const p=document.createElement('span');
  p.className='petal';
  p.style.left=Math.random()*100+'vw';
  p.style.animationDuration=(14+Math.random()*12)+'s';
  p.style.animationDelay=(-Math.random()*20)+'s';
  p.style.transform='scale('+(.7+Math.random()*.8)+')';
  document.body.appendChild(p)
}
const $=id=>document.getElementById(id);
const show=id=> {
  document.querySelectorAll('.scene').forEach(s=>s.classList.remove('on'));
  $(id).classList.add('on')
};
$('who1').textContent=HER_NAME;
$('date').textContent=DATE_TEXT;
$('place').textContent=PLACE_TEXT;
$('who2').textContent=HER_NAME==='ты'?'тебя':HER_NAME;
$('tk').textContent=DATE_TEXT+' · '+PLACE_TEXT;
const glow=document.createElement('div');
glow.id='glow';
$('card').appendChild(glow);
let ready=false,
idx=0,
ctx,
drawing=false,
cleared=false,
cv=$('cv');
function loadScene() {
  const s=SCENES[idx];
  $('cap').textContent=s.cap;
  $('card').classList.remove('done');
  const n=s.imgs.length||2;
  let h='';
  for(let i=0;i<n;i++)h+='<div class="poloroid">'+(s.imgs[i]?'<img alt="" src="'+s.imgs[i]+'">':'<div class="ph">Здесь будет фото</div>')+'</div>';
  $('under').innerHTML='<div class="ttl"></div><div class="fact"></div><div class="pics">'+h+'</div>';
  $('under').querySelector('.ttl').textContent=s.title;
  $('under').querySelector('.fact').textContent=s.fact;
  ready=false;
  cv.style.pointerEvents='';
  $('hint').textContent='Води пальцем — включай проектор';
  $('hint').style.display='';
  show('scratch');
  requestAnimationFrame(setupCanvas);
}
function setupCanvas() {
  const r=cv.getBoundingClientRect(),
  d=window.devicePixelRatio||1;
  cv.width=r.width*d;
  cv.height=r.height*d;
  ctx=cv.getContext('2d');
  ctx.scale(d,d);
  cleared=false;
  ctx.globalCompositeOperation='source-over';
  ctx.fillStyle='#12060b';
  ctx.fillRect(0,0,r.width,r.height);
  for(let i=0;i<1400;i++) {
    ctx.fillStyle='rgba(243,230,208,'+(Math.random()*.09)+')';
    ctx.fillRect(Math.random()*r.width,Math.random()*r.height,1+Math.random()*1.5,1+Math.random()*1.5)
  }
  ctx.fillStyle='#f0cf8f22';
  for(let y=10;y<r.height;y+=26) {
    ctx.fillRect(6,y,10,14);
    ctx.fillRect(r.width-16,y,10,14)
  }
  ctx.fillStyle='#f0cf8f';
  ctx.font='34px "Great Vibes",cursive';
  ctx.textAlign='center';
  ctx.fillText('Кадр '+(idx+1),r.width/2,r.height/2);
  ctx.globalCompositeOperation='destination-out';
}
function pos(e) {
  const r=cv.getBoundingClientRect();
  return {
    x:e.clientX-r.left,
    y:e.clientY-r.top
  }
}
function erase(e) {
  if(!drawing||cleared)return;
  const p=pos(e),
  R=46,
  g=ctx.createRadialGradient(p.x,p.y,0,p.x,p.y,R);
  g.addColorStop(0,'rgba(0,0,0,1)');
  g.addColorStop(.55,'rgba(0,0,0,.85)');
  g.addColorStop(1,'rgba(0,0,0,0)');
  ctx.fillStyle=g;
  ctx.beginPath();
  ctx.arc(p.x,p.y,R,0,7);
  ctx.fill();
  glow.style.opacity=1;
  glow.style.left=p.x+'px';
  glow.style.top=p.y+'px';
}
function coverage() {
  const w=cv.width,
  h=cv.height,
  data=ctx.getImageData(0,0,w,h).data;
  let clear=0,
  n=0;
  for(let i=3;i<data.length;i+=4*400) {
    n++;
    if(data[i]<70)clear++
  }
  return clear/n;
}
function finishScene() {
  cleared=true;
  cv.style.transition='opacity .6s';
  cv.style.opacity=0;
  cv.style.pointerEvents='none';
  glow.style.opacity=0;
  $('hint').style.display='none';
  setTimeout(()=> {
    $('card').classList.add('done')
  }
  ,1200);
  setTimeout(()=> {
    ready=true;$('hint').textContent='Коснись кадра — плёнка перемотается';$('hint').style.display=''
  }
  ,3600);
}
function roll(next) {
  const card=$('card');
  document.body.classList.add('roll');
  card.classList.add('out');
  setTimeout(()=> {
    card.classList.add('pre');card.classList.remove('out');cv.style.transition='';cv.style.opacity=1;next();void card.offsetWidth;card.classList.remove('pre')
  }
  ,760);
  setTimeout(()=>document.body.classList.remove('roll'),1700);
}
$('card').addEventListener('click',()=> {
  if(!ready)return;ready=false;idx++;   roll(()=> {
    if(idx<SCENES.length)loadScene();else {
      si=0;showStat()
    }
  });
});
let si=0,
sReady=false,
clockTimer=null;
function pad(n) {
  return String(n).padStart(2,'0')
}
function tickClock() {
  const ms=Date.now()-START_DT.getTime();
  const h=Math.floor(ms/3600000)%24,
  m=Math.floor(ms/60000)%60,
  sec=Math.floor(ms/1000)%60;
  $('clock').textContent=pad(h)+' : '+pad(m)+' : '+pad(sec);
}
function showStat() {
  if(clockTimer) {
    clearInterval(clockTimer);
    clockTimer=null
  }
  const raw=STATS[si],
  num=$('num');
  const st=raw.timer? {
    n:Math.floor((Date.now()-START_DT.getTime())/86400000),
    label:raw.label
  }
  :raw;
  show('stats');
  $('stats').classList.remove('settle');
  num.className='num';
  num.textContent='0';
  $('lab').textContent=st.label;
  $('shint').style.visibility='hidden';
  $('clock').classList.remove('on');
  $('clock').textContent='';
  sReady=false;
  requestAnimationFrame(()=> {
    num.classList.add('in');     const t0=performance.now()+700,D=2400;     (function step(now) {
      const p=Math.min(Math.max((now-t0)/D,0),1),e=1-Math.pow(1-p,3);       num.textContent=Math.round(st.n*e).toLocaleString('ru-RU');       if(p<1)requestAnimationFrame(step);       else setTimeout(()=> {
        num.classList.add('sm');$('stats').classList.add('settle');         if(raw.timer) {
          tickClock();$('clock').classList.add('on');clockTimer=setInterval(tickClock,1000)
        }
        setTimeout(()=> {
          sReady=true;$('shint').style.visibility='visible'
        }
        ,1600)
      }
      ,600);
    }
    )(performance.now());
  });
}
$('stats').addEventListener('click',()=> {
  if(!sReady)return;   if(clockTimer) {
    clearInterval(clockTimer);clockTimer=null
  }
  si++;if(si<STATS.length)showStat();else show('voice');
});
cv.addEventListener('pointerdown',e=> {
  drawing=true;cv.setPointerCapture(e.pointerId);erase(e)
});
cv.addEventListener('pointermove',e=> {
  erase(e)
});
const up=()=> {
  glow.style.opacity=0;
  if(!drawing)return;
  drawing=false;
  if(!cleared&&coverage()>0.5)finishScene()
};
cv.addEventListener('pointerup',up);
cv.addEventListener('pointercancel',up);
$('start').onclick=()=> {
  idx=0;
  const c=$('card');
  c.classList.add('pre');
  loadScene();
  void c.offsetWidth;
  c.classList.remove('pre')
};
/* Голосовое */
const audio=new Audio();
if(AUDIO_SRC)audio.src=AUDIO_SRC;
let played=false;
function reveal() {
  $('play').classList.remove('go');
  setTimeout(()=>show('ask'),1600)
}
$('play').onclick=()=> {
  if(!AUDIO_SRC) {
    $('vnote').textContent='Здесь прозвучит моё голосовое';
    reveal();
    return
  }
  if(audio.paused) {
    audio.play();
    $('play').textContent='❚❚';
    $('play').classList.remove('go')
  }
  else {
    audio.pause();
    $('play').textContent='▶'
  }
};
audio.onended=()=> {
  $('play').textContent='▶';
  reveal()
};
/* Вопрос */
const heart=$('heart');
let t0=0,
raf=0,
holding=false;
function tick() {
  if(!holding)return;
  const p=Math.min((performance.now()-t0)/1800,1);
  heart.style.setProperty('--p',(p*360)+'deg');
  if(p>=1) {
    holding=false;
    accept();
    return
  }
  raf=requestAnimationFrame(tick);
}
function hold(e) {
  e.preventDefault();
  if(holding)return;
  holding=true;
  t0=performance.now();
  heart.classList.remove('beat');
  raf=requestAnimationFrame(tick)
}
function release() {
  holding=false;
  cancelAnimationFrame(raf);
  heart.style.setProperty('--p','0deg');
  heart.classList.add('beat')
}
heart.addEventListener('pointerdown',hold);
['pointerup',
'pointerleave',
'pointercancel'].forEach(ev=>heart.addEventListener(ev,release));
heart.addEventListener('keydown',e=> {
  if(e.key===' '||e.key==='Enter')hold(e)
});
heart.addEventListener('keyup',release);
function accept() {
  show('done');
  for(let i=0;i<22;i++) {
    const f=document.createElement('span');
    f.className='fl';
    f.textContent=['♥',
    '❤',
    '💗'][i%3];
    f.style.left=Math.random()*95+'vw';
    f.style.animationDelay=(Math.random()*1.2)+'s';
    document.body.appendChild(f);
    setTimeout(()=>f.remove(),5000)
  }
}
const no=$('no');
function dodge() {
  const bw=no.offsetWidth,
  bh=no.offsetHeight;
  const x=Math.random()*(innerWidth-bw-24)+12,
  y=Math.random()*(innerHeight*0.6-bh)+innerHeight*0.25;
  no.style.left=x+'px';
  no.style.top=y+'px';
}
['pointerenter',
'pointerdown',
'touchstart'].forEach(ev=>no.addEventListener(ev,e=> {
  if(no.style.position!=='fixed') {
    const r=no.getBoundingClientRect();no.style.position='fixed';no.style.left=r.left+'px';no.style.top=r.top+'px';
  }
  e.preventDefault();dodge();
}
, {
  passive:false
}));